// Redis commands demonstrated via ioredis (Node.js client)
// npm install ioredis

import Redis from 'ioredis';
const redis = new Redis({ host: 'localhost', port: 6379 });

// ── String: cache a user profile for 5 minutes ──────────────
async function getUserProfile(userId) {
  const cacheKey = `user:${userId}`;

  // 1. Check cache
  const cached = await redis.get(cacheKey);
  if (cached) {
    return JSON.parse(cached); // cache HIT — ~0.1 ms
  }

  // 2. Cache miss — query database
  const user = await db.query('SELECT * FROM users WHERE id = $1', [userId]);

  // 3. Populate cache with 300-second TTL
  await redis.set(cacheKey, JSON.stringify(user), 'EX', 300);
  return user;
}

// ── Hash: store session data ─────────────────────────────────
async function createSession(sessionId, userId, role) {
  await redis.hset(`session:${sessionId}`,
    'user_id', userId,
    'role', role,
    'created_at', Date.now()
  );
  await redis.expire(`session:${sessionId}`, 3600); // 1-hour TTL
}

async function getSessionRole(sessionId) {
  return redis.hget(`session:${sessionId}`, 'role');
}

// ── Sorted Set: leaderboard ───────────────────────────────────
async function recordScore(userId, points) {
  // ZADD is O(log n) — sorted set keeps members ordered by score
  await redis.zadd('leaderboard:weekly', points, `user:${userId}`);
}

async function getTopTen() {
  // ZREVRANGE returns members highest-score-first
  return redis.zrevrange('leaderboard:weekly', 0, 9, 'WITHSCORES');
}

// ── String: rate limiting with atomic INCR ───────────────────
async function checkRateLimit(userId, limitPerMinute) {
  const minute = Math.floor(Date.now() / 60000);
  const key = `rate:${userId}:${minute}`;

  const count = await redis.incr(key); // atomic — no race condition
  if (count === 1) {
    await redis.expire(key, 60); // set TTL on first increment
  }
  return count <= limitPerMinute;
}

// ── String NX: distributed lock ───────────────────────────────
async function acquireLock(resource, ttlSeconds) {
  // SET NX EX is atomic — either you set it or you don't
  const result = await redis.set(
    `lock:${resource}`,
    'acquired',
    'NX',   // only if Not eXists
    'EX',   // with expiry
    ttlSeconds
  );
  return result === 'OK'; // OK = lock acquired; null = already held
}

// Elasticsearch / OpenSearch via @elastic/elasticsearch (Node.js)
// npm install @elastic/elasticsearch

import { Client } from '@elastic/elasticsearch';
const es = new Client({ node: 'http://localhost:9200' });

// ── 1. Create an index with field mappings ───────────────────
await es.indices.create({
  index: 'products',
  body: {
    settings: {
      analysis: {
        analyzer: {
          english_custom: {
            type: 'custom',
            tokenizer: 'standard',
            filter: ['lowercase', 'english_stemmer', 'stop']
          }
        },
        filter: {
          english_stemmer: { type: 'stemmer', language: 'english' }
        }
      }
    },
    mappings: {
      properties: {
        name:        { type: 'text', analyzer: 'english_custom', boost: 3 },
        description: { type: 'text', analyzer: 'english_custom' },
        category:    { type: 'keyword' },  // exact match, not analysed
        price:       { type: 'float' },
        in_stock:    { type: 'boolean' }
      }
    }
  }
});

// ── 2. Index a document ──────────────────────────────────────
await es.index({
  index: 'products',
  id: 'prod-001',
  document: {
    name: 'Wireless Mechanical Keyboard',
    description: 'Ultra-fast wireless keyboard for gaming and typing',
    category: 'peripherals',
    price: 129.99,
    in_stock: true
  }
});

// ── 3. Full-text search with filtering ───────────────────────
const result = await es.search({
  index: 'products',
  body: {
    query: {
      bool: {
        must: [
          {
            multi_match: {
              query: 'wireless keyboard gaming',
              fields: ['name^3', 'description'],  // name boosted 3x
              type: 'best_fields',
              fuzziness: 'AUTO'  // tolerates 1-2 typos
            }
          }
        ],
        filter: [
          { term: { in_stock: true } },
          { range: { price: { lte: 200 } } }
        ]
      }
    },
    highlight: {
      fields: { description: {} }  // return matched snippets
    },
    size: 10
  }
});

for (const hit of result.hits.hits) {
  console.log(`Score: ${hit._score.toFixed(2)} | ${hit._source.name}`);
}
